  delivered=0; steps=0; seconds=0; started=false; queuedPath=[]; autoMoving=false;
  clearInterval(timer);
  msg.textContent="Use arrows/WASD, buttons, or tap a reachable square.";
  render();
}
function startClock(){
  if(started)return;
  started=true;
  timer=setInterval(()=>{seconds++; timeEl.textContent=seconds},1000);
}
function render(){
  grid.innerHTML="";
  leftEl.textContent=parcels.length-delivered;
  stepsEl.textContent=steps;
  timeEl.textContent=seconds;
  for(let y=0;y<H;y++){
    for(let x=0;x<W;x++){
      const c=document.createElement("div");
      c.className="cell";
      c.dataset.x=x; c.dataset.y=y;
      if(desks.has(key(x,y))){c.classList.add("desk"); c.textContent="▦"}
      else if(cart.x===x&&cart.y===y){c.classList.add("cart"); c.textContent="🛒"}
      else if(hasParcel(x,y)){c.classList.add("parcel"); c.textContent="📦"}
      else if(parcels.some(p=>p.x===x&&p.y===y&&p.done)){c.classList.add("done"); c.textContent="✓"}
      else c.textContent="";
      if(queuedPath.some(p=>p.x===x&&p.y===y)) c.classList.add("path");
      c.addEventListener("pointerdown",cellTap);
      grid.appendChild(c);
    }
  }
}
function move(dx,dy, keepQueuedPath=false){
  if(delivered===parcels.length)return;
  startClock();
  if(!keepQueuedPath){
    queuedPath=[];
    autoMoving=false;
  }
  const nx=cart.x+dx, ny=cart.y+dy;
  if(blocked(nx,ny)){
    msg.textContent="Desk jam. Route around the office furniture.";
    render();
    return false;
  }
  cart.x=nx; cart.y=ny; steps++;
  checkDelivery();
  render();
  return true;
}
function checkDelivery(){
  const p=parcels.find(p=>p.x===cart.x&&p.y===cart.y&&!p.done);
  if(p){
    p.done=true; delivered++;
    msg.textContent="Parcel delivered.";
    if(delivered===parcels.length) finish();
  }
}
function finish(){
  clearInterval(timer);
  queuedPath=[];
  autoMoving=false;
  const score=Math.max(100,1000-steps*18-seconds*6);
  const best=Number(localStorage.mailroomBest||0);
  if(score>best){
    localStorage.mailroomBest=score;
    bestEl.textContent=score;
    msg.textContent=`Route complete. Score ${score}. New best.`;
  } else {
    msg.textContent=`Route complete. Score ${score}. Best ${best}.`;
  }
  render();
}
function cellTap(e){
  if(delivered===parcels.length)return;
  const x=+e.currentTarget.dataset.x, y=+e.currentTarget.dataset.y;
  if(blocked(x,y))return;
  const path=findPath(cart,{x,y});
  if(path.length<2){
    msg.textContent="Already there.";
    return;
  }
  queuedPath=path.slice(1);
  autoMoving=true;
  msg.textContent="Following tapped route.";
  render();
  setTimeout(autoStep,90);
}
function autoStep(){
  if(!autoMoving || !queuedPath.length || delivered===parcels.length){
    autoMoving=false;
    queuedPath=[];
    render();
    return;
  }
  const next=queuedPath.shift();
  const dx=next.x-cart.x, dy=next.y-cart.y;
  const moved=move(dx,dy,true);
  if(moved && queuedPath.length){
    setTimeout(autoStep,110);
  } else {
    autoMoving=false;
    queuedPath=[];
    render();
  }
}
function findPath(a,b){
  const q=[{x:a.x,y:a.y}], prev={}, seen=new Set([key(a.x,a.y)]);
  while(q.length){
    const n=q.shift();
    if(n.x===b.x&&n.y===b.y)break;
    [[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{
      const x=n.x+dx,y=n.y+dy,k=key(x,y);
      if(!blocked(x,y)&&!seen.has(k)){
        seen.add(k); prev[k]=n; q.push({x,y});
      }
    });
  }
  if(!seen.has(key(b.x,b.y)))return [];
  const path=[]; let cur={x:b.x,y:b.y};
  while(cur){path.unshift(cur); cur=prev[key(cur.x,cur.y)]}
  return path;
}
document.addEventListener("keydown",e=>{
  const k=e.key.toLowerCase();
  if(["arrowup","arrowdown","arrowleft","arrowright","w","a","s","d"].includes(k)) e.preventDefault();
  if(k==="arrowup"||k==="w")move(0,-1);
  if(k==="arrowdown"||k==="s")move(0,1);
  if(k==="arrowleft"||k==="a")move(-1,0);
  if(k==="arrowright"||k==="d")move(1,0);
  if(k==="r")newGame();
});
newGame();
